// Verify the caller and turn the profile into search terms.
// Replace SECRET with the same value you put in COPILOT_SUPPLY_SECRET.
const SECRET = 'REPLACE_WITH_COPILOT_SUPPLY_SECRET';

const req = $input.first().json;
const authorized = !SECRET || (req.headers?.authorization || '') === `Bearer ${SECRET}`;

const body = req.body ?? {};
const p = body.profile ?? {};
const offer = p.offer ?? {};

// Search on what this person actually sells, not on a hardcoded vertical.
// The app sends offer.{sells,for_who,problem}, target_segments and target_area.
const terms = [offer.for_who, offer.sells, ...(p.target_segments ?? [])]
  .filter(Boolean)
  .flatMap((s) => String(s).toLowerCase().split(/[,/]| and /))
  .map((s) => s.trim())
  .filter((s) => s.length > 2);

return [{
  json: {
    authorized,
    limit: Math.min(Number(body.limit) || 40, 50),
    area: p.target_area || p.location || '',
    terms,
    offer,
  },
}];

// Turn one source's rows into the contract the app expects.
// Required per row: external_id (stable across runs — this is how dedupe works)
// and title. Everything else is optional and normalised app-side.
const plan = $('Authorize & plan').first().json;
const terms = plan.terms ?? [];

// RemoteOK returns a JSON array whose first element is a legal notice.
// Depending on your n8n version the HTTP node hands that back as one item
// containing an array, or as many items. Handle both.
const raw = $input.all().map((i) => i.json);
const rows = raw.length === 1 && Array.isArray(raw[0]) ? raw[0] : raw;

const candidates = [];
for (const j of rows) {
  if (!j || !j.id || !j.position) continue;              // legal notice / junk
  const tags = Array.isArray(j.tags) ? j.tags : [];
  const hay = `${j.position} ${j.company ?? ''} ${tags.join(' ')} ${j.description ?? ''}`.toLowerCase();
  // No terms yet (empty offer) -> let everything through rather than nothing.
  if (terms.length && !terms.some((t) => hay.includes(t))) continue;

  candidates.push({
    source: 'remoteok',
    external_id: `remoteok:${j.id}`,
    type: 'client',
    title: `${j.position}${j.company ? ` — ${j.company}` : ''}`,
    // Facts only. The agent decides what it means and how to word it.
    summary: [
      j.company ? `${j.company} is hiring for ${j.position}.` : `${j.position}.`,
      tags.length ? `Stack: ${tags.slice(0, 6).join(', ')}.` : null,
      j.location ? `Location: ${j.location}.` : null,
      j.date ? `Posted ${String(j.date).slice(0, 10)}.` : null,
    ].filter(Boolean).join(' '),
    url: j.url || j.apply_url || null,
    // Job boards give a link, not a phone number. With no contact the app
    // shows the match and the link but offers no drafted message — which is
    // correct, there is nobody to message yet.
    contact: { website: j.company_url || undefined },
    effort: 'medium',
    value_label: j.salary_min ? `$${Number(j.salary_min).toLocaleString()}+` : undefined,
    data: { tags, location: j.location, posted: j.date, board: 'remoteok' },
  });
}

return [{ json: { candidates: candidates.slice(0, plan.limit) } }];
